"""Glossary lookup for Global Food Security Forecasting Engines."""

GLOSSARY = {
    "desalination": "removing salt from seawater to make freshwater",
    "precision irrigation": "delivering water to each plant according to its needs",
    "cold chain": "the unbroken refrigerated path from farm to consumer",
    "nutrient cycling": "returning nitrogen, phosphorus, and organics to productive use",
    "food security": "reliable access to sufficient, safe, nutritious food",
    "aquifer": "an underground layer holding usable groundwater",
}

def lookup(term):
    key = term.strip().lower()
    for k, v in GLOSSARY.items():
        if k.lower() == key:
            return k + ": " + v
    cands = [k for k in GLOSSARY if key in k.lower()]
    return ("Did you mean: " + ", ".join(cands)) if cands else "No entry."


if __name__ == "__main__":
    print("Global Food Security Forecasting Engines glossary — %d terms" % len(GLOSSARY))
    for t in list(GLOSSARY)[:3]:
        print("-", lookup(t))

"""Piece model: Source Capture — part of the Global Food Security Forecasting Engines system."""
import random

class GlobalFoodSecurityForecastingEnginesPiece1SourceCapture:
    """Models the Source Capture piece: specification check and behavior sample."""

    SPEC = {"piece": "Source Capture", "interfaces": 3, "redundancy": 2}

    def __init__(self, seed=11):
        self.rng = random.Random(seed)

    def spec_check(self):
        """Verify the piece meets its interface contract."""
        results = {}
        for i in range(self.SPEC["interfaces"]):
            # simulated conformance measurement around a nominal value
            measured = 1.0 + self.rng.uniform(-0.04, 0.04)
            results["interface_%d" % i] = round(measured, 3)
        ok = all(0.94 <= v <= 1.06 for v in results.values())
        return {"pass": ok, "measurements": results}

    def simulate(self, cycles=24):
        """Sample operating behavior over a number of cycles."""
        health = 1.0
        for _ in range(cycles):
            stress = self.rng.uniform(0.0, 0.06)
            health = max(0.0, health - stress * 0.2)
            health = min(1.0, health + 0.05)  # recovery / maintenance
        return {"cycles": cycles, "health": round(health, 3),
                "redundancy_ok": health > 0.5}


if __name__ == "__main__":
    m = GlobalFoodSecurityForecastingEnginesPiece1SourceCapture(seed=11)
    sc = m.spec_check()
    sm = m.simulate(24)
    print("Source Capture — Global Food Security Forecasting Engines")
    print("spec check pass:", sc["pass"], "| measurements:", sc["measurements"])
    print("health after", sm["cycles"], "cycles:", sm["health"])

