"""Energy and resource balance model — model for Global Food Security Forecasting Engines.
Domain: water, food, and global resource security. Deterministic demonstration model (seeded).
"""
import random

class GlobalFoodSecurityForecastingEnginesSim:
    """Hour-by-hour balance of supply, demand, storage, and losses."""

    def __init__(self, capacity=100.0, storage=240.0, seed=7):
        self.rng = random.Random(seed)
        self.capacity = capacity      # peak supply units
        self.storage = storage        # storage capacity (unit-hours)
        self.charge = storage * 0.5
        self.loss_factor = 0.92       # storage round-trip factor per cycle

    def simulate_day(self, demand_profile):
        unmet, curtailed = 0.0, 0.0
        for h, demand in enumerate(demand_profile):
            # supply varies through the day (illustrative profile)
            supply = self.capacity * max(0.0, 0.9 - 0.08 * abs(h - 13))
            net = supply - demand
            if net >= 0:
                room = self.storage - self.charge
                store = min(net * self.loss_factor, room)
                self.charge += store
                curtailed += net - store / self.loss_factor if self.loss_factor else 0.0
            else:
                draw = min(-net, self.charge)
                self.charge -= draw
                unmet += -net - draw
        return {"unmet_demand": round(unmet, 1), "curtailed": round(max(0.0, curtailed), 1),
                "end_charge": round(self.charge, 1)}

    def report_week(self):
        tot_unmet = 0.0
        for _ in range(7):
            demand = [38 + 22 * (1 if 7 <= h <= 21 else 0.4) + self.rng.uniform(-4, 4)
                      for h in range(24)]
            tot_unmet += self.simulate_day(demand)["unmet_demand"]
        return {"week_unmet": round(tot_unmet, 1),
                "reliability_pct": round(100 * max(0.0, 1 - tot_unmet / (7 * 24 * 50)), 2)}


if __name__ == "__main__":
    m = GlobalFoodSecurityForecastingEnginesSim(capacity=100.0, storage=240.0, seed=7)
    r = m.report_week()
    print("Global Food Security Forecasting Engines energy balance model")
    print("week unmet demand:", r["week_unmet"], "| reliability:", r["reliability_pct"], "%")
